from typing import List, Dict, Any

def longest_unique_substring(s: str) -> int:
    char_index = {}
    max_len = 0
    left = 0
    for right, char in enumerate(s):
        if char in char_index and char_index[char] >= left:
            left = char_index[char] + 1
        char_index[char] = right
        max_len = max(max_len, right - left + 1)
    return max_len

def explain_approach() -> dict:
    return {
        'brute_force': {
            'description': 'Her alt-string icin tekrar kontrolu',
            'time': 'O(n^3)',
            'space': 'O(min(n, m))'
        },
        'optimal': {
            'description': 'Sliding window + HashMap ile son pozisyon takibi',
            'time': 'O(n)',
            'space': 'O(min(n, m))'
        },
        'why_optimal': 'HashMap ile tekrar eden karakterin son pozisyonunu bildigimiz icin left pointer'i dogrudan atlatabiliriz. Set versiyonunda left'i tek tek ilerletmek gerekirdi.'
    }

