function longestUniqueSubstring(s) {
    const charIndex = new Map();
    let maxLen = 0, left = 0;
    for (let right = 0; right < s.length; right++) {
        if (charIndex.has(s[right]) && charIndex.get(s[right]) >= left) {
            left = charIndex.get(s[right]) + 1;
        }
        charIndex.set(s[right], right);
        maxLen = Math.max(maxLen, right - left + 1);
    }
    return maxLen;
}

function explainApproach() {
    return {
        brute_force: { description: 'Check all substrings', time: 'O(n^3)', space: 'O(min(n,m))' },
        optimal: { description: 'Sliding window + HashMap', time: 'O(n)', space: 'O(min(n,m))' },
        why_optimal: 'HashMap tracks last position, allowing left pointer to jump directly.'
    };
}

